from bagimlilik import kurulum_sirasi, DonguHatasi

def test():
    # Test 1: Basit sıralama ve alfabetik kuralı
    deps1 = {"a": ["b"], "c": ["a", "b"]}
    assert kurulum_sirasi(deps1) == ["b", "a", "c"]

    # Test 2: Alfabetik öncelik (aynı anda kurulabilenler)
    deps2 = {"a": [], "b": [], "c": []}
    assert kurulum_sirasi(deps2) == ["a", "b", "c"]

    # Test 3: Karmaşık bağımlılıklar
    deps3 = {
        "A": ["B", "C"],
        "B": ["D"],
        "C": ["D"],
        "D": []
    }
    # D önce, sonra B ve C (alfabetik), en son A. 
    # Ancak B ve C aynı anda kurulabilirse alfabetik: D -> B -> C -> A veya D -> C -> B -> A?
    # Soru: "O an kurulabilecek birden fazla paket varsa alfabetik olarak en küçüğü önce gelsin"
    # D bittiğinde, B ve C'nin in_degree'si 0 olur. Alfabetik olarak B gelir.
    assert kurulum_sirasi(deps3) == ["D", "B", "C", "A"]

    # Test 4: Döngü (a -> b -> c -> a)
    deps4 = {"a": ["b"], "b": ["c"], "c": ["a"]}
    try:
        kurulum_sirasi(deps4)
        assert False, "Döngü hatası fırlatılmadı"
    except DonguHatasi as e:
        assert e.dongu == ["a", "b", "c"]

    # Test 5: Kendine bağımlılık (x -> x)
    deps5 = {"x": ["x"]}
    try:
        kurulum_sirasi(deps5)
        assert False, "Kendine bağımlılık hatası fırlatılmadı"
    except DonguHatasi as e:
        assert e.dongu == ["x"]

    # Test 6: Büyük döngü ve alfabetik başlangıç (a -> c -> b -> a)
    deps6 = {"a": ["c"], "c": ["b"], "b": ["a"]}
    try:
        kurulum_sirasi(deps6)
        assert False, "Döngü hatası fırlatılmadı"
    except DonguHatasi as e:
        # Döngü [a, c, b] veya [c, b, a] vb. 
        # Alfabetik en küçük 'a' ile başlamalı: ["a", "c", "b"]
        assert e.dongu == ["a", "c", "b"]

    # Test 7: Bağımlılık olarak geçen ama dict içinde olmayan paketler
    deps7 = {"A": ["B"]} # B de bir pakettir, sıralamada olmalı
    assert kurulum_sirasi(deps7) == ["B", "A"]

    print("Tüm testler başarıyla geçti!")

if __name__ == "__main__":
    test()

