class DonguHatasi(ValueError):
    def __init__(self, dongu: list[str]):
        self.dongu = dongu
        super().__init__(f"Bağımlılık döngüsü tespit edildi: {', '.join(dongu)}")

def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    # Tüm paketleri topla (bağımlılık olarak geçenler dahil)
    all_packages = set(deps.keys())
    for requirements in deps.values():
        for req in requirements:
            all_packages.add(req)

    graph = {pkg: [] for pkg in all_packages}
    in_degree = {pkg: 0 for pkg in all_packages}

    # Bağımlılıkları yönlendir: req -> pkg (req kurulunca pkg'nin bağımlılığı azalır)
    for pkg, requirements in deps.items():
        unique_reqs = set(requirements)
        for req in unique_reqs:
            if req == pkg:
                # Kendine bağımlılık durumu için in_degree artırılmalı ki Kahn yakalasın
                in_degree[pkg] += 1
            else:
                graph[req].append(pkg)
                in_degree[pkg] += 1

    import heapq
    queue = [pkg for pkg in all_packages if in_degree[pkg] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) < len(all_packages):
        # Döngü tespiti için DFS kullanıyoruz (orijinal bağımlılık yönünde: pkg -> req)
        visited = set()
        on_stack = []
        on_stack_set = set()
        cycle_found = []

        def find_cycle(u):
            nonlocal cycle_found
            visited.add(u)
            on_stack.append(u)
            on_stack_set.add(u)

            # Orijinal bağımlılık yönü: u -> req (u, req'e bağımlıdır)
            for v in deps.get(u, []):
                if v == u:
                    cycle_found = [u]
                    return True
                if v in on_stack_set:
                    idx = on_stack.index(v)
                    cycle_found = on_stack[idx:]
                    return True
                if v not in visited:
                    if find_cycle(v):
                        return True

            on_stack.pop()
            on_stack_set.remove(u)
            return False

        # Tüm paketleri tara, alfabetik olarak en küçük döngüyü bulmak için sıralı tarıyoruz
        for pkg in sorted(all_packages):
            if pkg not in visited:
                if find_cycle(pkg):
                    break

        if cycle_found:
            min_val = min(cycle_found)
            min_idx = cycle_found.index(min_val)
            ordered_cycle = cycle_found[min_idx:] + cycle_found[:min_idx]
            raise DonguHatasi(ordered_cycle)

    return result

